def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if not alive_opps:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    threat_bids = []
    rich_threat = 0.0
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('budget', 0) > DAILY_SALARY * 1.5:
                threat_bids.append(float(bid))
        if opp.get('budget', 0) > rich_threat:
            rich_threat = float(opp.get('budget', 0))

    high_prev = max(prev_bids) if prev_bids else 0.0
    high_threat_prev = max(threat_bids) if threat_bids else high_prev

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    urgency = 0
    if hp <= 2 or no_water_days >= 2:
        urgency = 3
    elif hp <= 4 or no_water_days >= 1:
        urgency = 2
    elif hp <= 6:
        urgency = 1

    if urgency >= 3:
        target = max(98.0, high_threat_prev + 3.0)
        if scarcity >= 1:
            target = max(target, 118.0)
        return float(min(budget, target))

    if scarcity >= 2:
        if high_threat_prev >= 130:
            target = high_threat_prev + 2.0
        else:
            target = 110.0 + 8.0 * urgency
        return float(min(budget, target))

    if scarcity == 1:
        if high_threat_prev >= 130:
            if hp >= 7 and no_water_days == 0 and budget < rich_threat:
                return float(min(budget, 32.0))
            target = 96.0 + 8.0 * urgency
            return float(min(budget, target))
        target = max(55.0, high_threat_prev + 2.0)
        return float(min(budget, target))

    if high_threat_prev >= 130:
        if hp >= 7 and no_water_days == 0:
            return float(min(budget, 24.0))
        return float(min(budget, 88.0))

    if high_prev > 0:
        target = max(38.0, high_prev * 0.72 + 2.0 * urgency)
        return float(min(budget, target))

    base = 30.0
    if day >= 8:
        base = 42.0
    if urgency >= 1:
        base += 18.0
    return float(min(budget, base))

def get_bid(day_context, my_status, opponents_status):
    MY_WATER_REQ = 13
    MY_DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], MY_DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    total_water_needed = MY_WATER_REQ + sum(o['water_requirement'] for o in alive_opponents)
    is_supply_tight = day_context['supply'] < total_water_needed

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= MY_DAILY_SALARY * 0.85:
            if my_status['hp'] > 3:
                if is_supply_tight:
                    return min(my_status['budget'], max(MY_DAILY_SALARY * 0.7, highest_prev_bid * 0.9))
                else:
                    return min(my_status['budget'], MY_DAILY_SALARY * 0.5)
            else:
                return min(my_status['budget'], MY_DAILY_SALARY * 0.95)
        else:
            return min(my_status['budget'], max(MY_DAILY_SALARY * 0.55, highest_prev_bid + 2.0))
    else:
        if my_status['hp'] <= 2 or day_context['day'] >= EPISODE_DAYS - 2:
            return min(my_status['budget'], MY_DAILY_SALARY * 0.95)
        else:
            return min(my_status['budget'], MY_DAILY_SALARY * 0.6)

